#!/usr/bin/env python3
"""surface_guard — prove the surface map is coherent and changes stay inside it.

Usage:
  surface_guard.py check [--root DIR] [--files-from FILE]
  surface_guard.py diff AGENT [--root DIR] [--base REF] [--files-from FILE]
  surface_guard.py diff --range BASE..HEAD [--branch NAME] [--root DIR] [--commits-from FILE]
  surface_guard.py whois PATH... [--root DIR]
  surface_guard.py charters [--check | --write] [--root DIR]

Reads governance/SURFACES.md (OPERATING_MODEL.md section 8; specs S-001, S-002).
`diff --range` walks every commit in BASE..HEAD and checks who wrote it (agent
identity or the humans block), its Agent-Session/Spec trailers, the paths it
touched, the build-branch rule and test-author independence. Merge commits and
commits in the `exempt` block are skipped. Commits are judged against the
surface map in the working tree at --root.
`charters` checks (or rewrites) the generated Surface section of every
builder-class agent's .claude/agents/<id>.md, between the markers
<!-- surface:begin --> and <!-- surface:end --> (spec S-003 §4).
Exit 0 = pass, 1 = rule violated, 2 = usage or parse error.
"""

import argparse
import json
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import govlib as g  # noqa: E402

SF = g.SURFACES_REL


def tracked_files(root):
    return sorted(set(g.split_z(g.git(root, ["ls-files", "-z"]))))


def changed_files(root, base=None):
    files = set()
    if base:
        files.update(g.split_z(g.git(root, ["diff", "--name-only", "--no-renames", "-z", "--relative",
                                            "%s...HEAD" % base])))
    if g.git_ok(root, ["rev-parse", "--verify", "-q", "HEAD"]):
        files.update(g.split_z(g.git(root, ["diff", "--name-only", "--no-renames", "-z", "--relative", "HEAD"])))
    else:
        # No commits yet: everything staged is a change.
        files.update(g.split_z(g.git(root, ["diff", "--name-only", "--no-renames", "-z", "--relative", "--cached"])))
    files.update(g.split_z(g.git(root, ["ls-files", "--others", "--exclude-standard", "-z"])))
    return sorted(files)


def structure_violations(s):
    """Rules about the map itself. Returns (violations, notes)."""
    v = []
    for lineno, msg in s.problems:
        v.append("%s line %d: %s" % (SF, lineno, msg))
    seen = {}
    for r in s.roster:
        where = "%s line %d" % (SF, r.lineno)
        if r.id == g.ORCHESTRATOR:
            v.append("%s: 'orchestrator' is reserved and must not have a roster row" % where)
        if r.id in seen:
            v.append("%s: duplicate roster id '%s' (first at line %d)" % (where, r.id, seen[r.id]))
        else:
            seen[r.id] = r.lineno
        if r.cls not in g.CLASSES:
            v.append("%s: '%s' has invalid class '%s' (must be one of: %s)"
                     % (where, r.id, r.cls, ", ".join(g.CLASSES)))
        if r.status not in g.STATUSES:
            v.append("%s: '%s' has invalid status '%s' (must be one of: %s)"
                     % (where, r.id, r.status, ", ".join(g.STATUSES)))
        if r.authority not in g.AUTHORITIES:
            v.append("%s: '%s' has invalid authority '%s' (must be one of: %s)"
                     % (where, r.id, r.authority, ", ".join(g.AUTHORITIES)))
    if g.ORCHESTRATOR not in s.blocks:
        v.append("%s: no surface:orchestrator block — the orchestrator's surface must be declared" % SF)
    for agent_id in sorted(seen):
        if agent_id != g.ORCHESTRATOR and agent_id not in s.blocks:
            v.append("%s: roster id '%s' has no surface:%s block — every roster row needs a surface"
                     % (SF, agent_id, agent_id))
    for agent_id in sorted(s.blocks):
        if agent_id != g.ORCHESTRATOR and agent_id not in seen:
            v.append("%s line %d: surface:%s block has no roster row — orphan surface"
                     % (SF, s.block_lines[agent_id], agent_id))
    for agent_id in sorted(set(s.reviewer_ids())):
        rules = s.blocks.get(agent_id) or []
        if rules:
            v.append("%s line %d: %s '%s' has globs in its surface block — reviewer-class agents are read-only"
                     % (SF, s.block_lines[agent_id], s.row(agent_id).cls, agent_id))
    notes = []
    defaulted = sorted(set(r.id for r in s.roster if r.defaulted))
    if defaulted:
        notes.append("NOTE: authority defaulted to 'autonomous' for: %s" % ", ".join(defaulted))
    return v, notes


def ownership_violations(s, files):
    v = []
    for path in sorted(set(files)):
        owners = s.owners(path)
        if not owners:
            v.append("%s: unowned — no surface in %s claims it (every path needs exactly one owner)" % (path, SF))
        elif len(owners) > 1:
            v.append("%s: claimed by %s — every path needs exactly one owner" % (path, ", ".join(owners)))
    return v


def exempt_violations(s, root):
    """Every exemption must name an entry heading in docs/LEDGER.md."""
    if not s.exempt:
        return []
    ledger = os.path.join(root, g.LEDGER_REL)
    if not os.path.isfile(ledger):
        return ["%s line %d: exempt %s cites %s, but %s is missing" % (SF, lineno, sha, lid, g.LEDGER_REL)
                for lineno, sha, lid in s.exempt]
    _, entries = g.parse_ledger(g.read_text(ledger))
    ids = set(e.id for e in entries)
    return ["%s line %d: exempt %s cites %s, which is not an entry in %s" % (SF, lineno, sha, lid, g.LEDGER_REL)
            for lineno, sha, lid in s.exempt if lid not in ids]


def known_agents(s):
    ids = set(s.roster_ids())
    ids.add(g.ORCHESTRATOR)
    return ids


def diff_violations(s, agent, files):
    """Raise UsageError for an unknown agent; else return violations."""
    if agent not in known_agents(s):
        raise g.UsageError("unknown agent '%s' — not in the %s roster and not 'orchestrator'" % (agent, SF))
    v = []
    files = sorted(set(files))
    row = s.row(agent)
    if row is not None and row.cls in g.REVIEWER_CLASSES:
        for path in files:
            v.append("%s: changed by %s '%s' — reviewers are read-only" % (path, row.cls, agent))
        return v
    for path in files:
        owners = s.owners(path)
        if owners == [agent]:
            continue
        if not owners:
            v.append("%s: outside the surface of '%s' (unowned)" % (path, agent))
        elif agent in owners:
            v.append("%s: claimed by %s, not by '%s' alone" % (path, ", ".join(owners), agent))
        else:
            v.append("%s: outside the surface of '%s' (owned by %s)" % (path, agent, ", ".join(owners)))
    return v


# --------------------------------------------------------------------------
# diff --range (spec S-002)


BUILD_BRANCH_RE = re.compile(r"^build/([^/]+)/(.+)$")
AUTH = "surface_guard.range.authorship"
TRAILERS = "surface_guard.range.trailers"


def is_test_author(agent_id):
    return agent_id == "test-author" or agent_id.startswith("test-author-")


def parse_range(rng):
    base, sep, head = rng.partition("..")
    if not sep:
        raise g.UsageError("--range %r must be BASE..HEAD" % rng)
    if head.startswith("."):
        raise g.UsageError("--range %r: use BASE..HEAD (two dots), not BASE...HEAD" % rng)
    if not base:
        raise g.UsageError("--range %r has no BASE" % rng)
    return base, head or "HEAD"


def _commit_from_json(obj, where):
    if not isinstance(obj, dict):
        raise g.UsageError("%s: each commit must be an object" % where)
    missing = [k for k in ("sha", "parents", "author_name", "author_email", "message", "paths") if k not in obj]
    if missing:
        raise g.UsageError("%s: commit is missing %s" % (where, ", ".join(missing)))
    if not isinstance(obj["parents"], list) or not isinstance(obj["paths"], list):
        raise g.UsageError("%s: 'parents' and 'paths' must be lists" % where)
    return g.Commit(str(obj["sha"]), [str(p) for p in obj["parents"]], str(obj["author_name"]),
                    str(obj["author_email"]), str(obj["message"]), [str(p) for p in obj["paths"]])


def load_commits_json(path):
    """Return (commits, history) from a --commits-from file."""
    text = g.read_text(path)
    try:
        data = json.loads(text)
    except ValueError as exc:
        raise g.UsageError("cannot read --commits-from %s: %s" % (path, exc))
    except RecursionError:
        raise g.UsageError("cannot read --commits-from %s: nested too deeply to parse" % path)
    history = None
    if isinstance(data, dict):
        unknown = sorted(set(data) - {"commits", "history"})
        if unknown or "commits" not in data:
            raise g.UsageError("--commits-from %s: the object form is {\"commits\": [...], \"history\": [...]}" % path)
        commits_raw = data["commits"]
        history_raw = data.get("history")
    else:
        commits_raw, history_raw = data, None
    if not isinstance(commits_raw, list) or (history_raw is not None and not isinstance(history_raw, list)):
        raise g.UsageError("--commits-from %s: 'commits' and 'history' must be lists" % path)
    commits = [_commit_from_json(o, path) for o in commits_raw]
    if history_raw is not None:
        history = [_commit_from_json(o, path) for o in history_raw]
    else:
        history = list(commits)
    return commits, [c for c in history if not c.is_merge()]


def load_commits_git(root, base, head):
    for ref in (base, head):
        if not g.git_ok(root, ["rev-parse", "--verify", "-q", "%s^{commit}" % ref]):
            raise g.UsageError("%r is not a commit in %s" % (ref, root))
    commits = g.read_commits(root, g.rev_list(root, ["--reverse", "%s..%s" % (base, head)]))
    for c in commits:
        if not c.is_merge():
            c.paths = g.commit_paths(root, c.sha)
    history = g.read_commits(root, g.rev_list(root, ["--no-merges", head]))
    return commits, history


def current_branch(root):
    try:
        return g.git(root, ["rev-parse", "--abbrev-ref", "HEAD"]).decode().strip()
    except g.GitError:
        return "HEAD"


def range_violations(s, commits, history, branch):
    """Return ([(check name, violation)], notes, counts) for a range walk."""
    v, notes = [], []
    roster = dict((r.id, r) for r in s.roster)
    humans = s.human_emails()
    exempt = s.exempt_map()

    branch_id = None
    if branch and branch.startswith("build/"):
        m = BUILD_BRANCH_RE.match(branch)
        if not m:
            v.append(("surface_guard.range.branch",
                      "branch %s is not build/<id>/<task> — no builder can be identified" % branch))
        elif m.group(1) not in roster or roster[m.group(1)].cls != "builder":
            v.append(("surface_guard.range.branch",
                      "branch build/%s/… names no builder — '%s' is not a builder-class roster id"
                      % (m.group(1), m.group(1))))
        else:
            branch_id = m.group(1)

    merges = [c for c in commits if c.is_merge()]
    n_exempt = n_human = 0
    checked = []
    for c in commits:
        if c.is_merge():
            continue
        lid = exempt.get(c.sha.lower())
        if lid is not None:
            n_exempt += 1
            notes.append("NOTE: %s: exempt (%s) — skipped" % (c.short, lid))
            continue
        checked.append(c)
        who = "%s <%s>" % (c.author_name, c.author_email)
        agent = c.agent_id()
        if agent is None:
            if c.author_email.lower() in humans:
                n_human += 1
                notes.append("NOTE: %s: human commit by %s — any path allowed" % (c.short, c.author_email))
                continue
            v.append((AUTH, "%s: unknown author %s — not an agent identity and not in the humans block"
                      % (c.short, who)))
            continue
        if agent != g.ORCHESTRATOR and agent not in roster:
            v.append((AUTH, "%s: unknown agent %s — '%s' is not in the %s roster" % (c.short, who, agent, SF)))
            continue
        if c.author_name != agent:
            v.append((AUTH, "%s: author name '%s' does not match agent id '%s' (%s)"
                      % (c.short, c.author_name, agent, c.author_email)))
        sessions = c.trailer("Agent-Session")
        if not sessions:
            v.append((TRAILERS, "%s: agent commit by '%s' has no Agent-Session trailer" % (c.short, agent)))
        elif len(sessions) > 1:
            v.append((TRAILERS, "%s: agent commit by '%s' has %d Agent-Session trailers — exactly one is required"
                      % (c.short, agent, len(sessions))))
        elif not sessions[0]:
            v.append((TRAILERS, "%s: agent commit by '%s' has an empty Agent-Session trailer" % (c.short, agent)))
        specs = c.trailer("Spec")
        if len(specs) > 1:
            v.append((TRAILERS, "%s: agent commit by '%s' has %d Spec trailers — at most one is allowed"
                      % (c.short, agent, len(specs))))
        if branch_id is not None and agent != branch_id:
            v.append(("surface_guard.range.branch", "%s: commit by '%s' on branch %s — only '%s' or a human may "
                      "commit there" % (c.short, agent, branch, branch_id)))
        if agent in roster and roster[agent].cls in g.REVIEWER_CLASSES:
            v.append((AUTH, "%s: commit by %s '%s' — reviewers never commit" % (c.short, roster[agent].cls, agent)))
            continue
        for line in diff_violations(s, agent, c.paths or []):
            v.append(("surface_guard.range.paths", "%s: %s" % (c.short, line)))

    v.extend(("surface_guard.range.independence", line) for line in independence_violations(s, checked, history))
    if merges:
        notes.insert(0, "NOTE: %d merge commit(s) skipped" % len(merges))
    return v, notes, (len(commits), len(merges), n_exempt, n_human)


def independence_violations(s, checked, history):
    """A session that wrote a spec's tests (test-author) must not also write its code."""
    roster = dict((r.id, r) for r in s.roster)
    specs = set()
    for c in checked:
        specs.update(x for x in c.trailer("Spec") if x)
    v = []
    for spec in sorted(specs):
        tests, code = {}, {}   # session -> set of ids
        for c in history:
            agent = c.agent_id()
            if agent is None or agent not in roster or roster[agent].cls != "builder":
                continue
            if spec not in c.trailer("Spec"):
                continue
            target = tests if is_test_author(agent) else code
            for session in c.trailer("Agent-Session"):
                if session:
                    target.setdefault(session, set()).add(agent)
        for session in sorted(set(tests) & set(code)):
            for ta in sorted(tests[session]):
                for coder in sorted(code[session]):
                    v.append("spec %s: session %s wrote both tests (%s) and code (%s)" % (spec, session, ta, coder))
    return v


def run_range(args, s):
    base, head = parse_range(args.range)
    if args.commits_from:
        commits, history = load_commits_json(args.commits_from)
        branch = args.branch
    else:
        commits, history = load_commits_git(args.root, base, head)
        branch = args.branch if args.branch is not None else current_branch(args.root)
    v, notes, (n, m, e, h) = range_violations(s, commits, history, branch)
    # The walk trusts the map, so a broken map (including an exemption that
    # cites no ledger entry) fails the walk too, not only `check`.
    map_v, _ = structure_violations(s)
    v = _tag(MAP, map_v + exempt_violations(s, args.root)) + v
    return g.report(args.root, v, notes, "%d commit(s) in %s checked (%d merge(s) skipped, %d exempt, %d human)"
                    % (n, args.range, m, e, h))


MAP = "surface_guard.map"


def _tag(name, lines):
    return [(name, line) for line in lines]


# --------------------------------------------------------------------------
# charters (spec S-003 §4)


AGENTS_REL = ".claude/agents"
CHARTER_BEGIN = "<!-- surface:begin -->"
CHARTER_END = "<!-- surface:end -->"
CHARTER_OWNER_LINE = "Owning file: %s (generated; do not edit)." % SF


def charter_lines(rules):
    """The generated Surface section: one '- <glob>' line per surface line, '!' kept."""
    return (["Writes:"] + ["- %s%s" % ("!" if neg else "", pattern) for neg, pattern in rules]
            + [CHARTER_OWNER_LINE])


def _marker_span(lines):
    """(begin index, end index) of the marker lines, or an error message."""
    begins = [i for i, l in enumerate(lines) if l.rstrip("\r") == CHARTER_BEGIN]
    ends = [i for i, l in enumerate(lines) if l.rstrip("\r") == CHARTER_END]
    if not begins or not ends:
        return None, "no %s … %s markers — the Surface section must sit between them" % (CHARTER_BEGIN, CHARTER_END)
    if len(begins) > 1 or len(ends) > 1 or ends[0] < begins[0]:
        return None, "the %s and %s markers must appear once each, in that order" % (CHARTER_BEGIN, CHARTER_END)
    return (begins[0], ends[0]), None


def check_charters(s, root, write=False):
    """Return (violations, notes). With write, rewrite stale sections (only between the markers)."""
    v, notes = [], []
    checked = 0
    for agent_id in sorted(set(s.builder_ids())):
        rel = "%s/%s.md" % (AGENTS_REL, agent_id)
        path = os.path.join(root, rel)
        if not os.path.isfile(path):
            notes.append("NOTE: builder '%s' has no %s; nothing to check" % (agent_id, rel))
            continue
        checked += 1
        text = g.read_text(path, newline="")
        lines = text.split("\n")
        span, err = _marker_span(lines)
        if err:
            v.append("%s: %s" % (rel, err))
            continue
        begin, end = span
        want = charter_lines(s.blocks.get(agent_id, []))
        have = [l[:-1] if l.endswith("\r") else l for l in lines[begin + 1:end]]
        if have == want:
            continue
        if not write:
            v.append("%s: the Surface section differs from surface:%s in %s — regenerate it with "
                     "surface_guard.py charters --write" % (rel, agent_id, SF))
            continue
        eol = "\r" if lines[begin].endswith("\r") else ""
        new = "\n".join(lines[:begin + 1] + [l + eol for l in want] + lines[end:])
        with open(path, "wb") as fh:
            fh.write(new.encode("utf-8"))
        notes.append("wrote %s" % rel)
    return v, notes, checked


def main(argv=None):
    parser = argparse.ArgumentParser(prog="surface_guard.py", description=__doc__.split("\n")[0])
    sub = parser.add_subparsers(dest="cmd")
    p_check = sub.add_parser("check")
    p_check.add_argument("--root", default=".")
    p_check.add_argument("--files-from")
    p_diff = sub.add_parser("diff")
    p_diff.add_argument("agent", nargs="?")
    p_diff.add_argument("--root", default=".")
    p_diff.add_argument("--base")
    p_diff.add_argument("--files-from")
    p_diff.add_argument("--range", dest="range")
    p_diff.add_argument("--branch")
    p_diff.add_argument("--commits-from")
    p_who = sub.add_parser("whois")
    p_who.add_argument("paths", nargs="+")
    p_who.add_argument("--root", default=".")
    p_ch = sub.add_parser("charters")
    p_ch.add_argument("--root", default=".")
    mode = p_ch.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true")
    mode.add_argument("--write", action="store_true")
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return 2 if exc.code else 0
    if not args.cmd:
        parser.print_usage(sys.stderr)
        return 2
    if args.cmd == "diff":
        usage = None
        if (args.agent is None) == (args.range is None):
            usage = "diff takes exactly one of AGENT and --range BASE..HEAD"
        elif args.range is not None and (args.base or args.files_from):
            usage = "--base and --files-from do not apply to diff --range (use --commits-from)"
        elif args.range is None and (args.branch is not None or args.commits_from):
            usage = "--branch and --commits-from apply only to diff --range"
        if usage:
            print("ERROR: %s" % usage, file=sys.stderr)
            return 2
    try:
        s = g.load_surfaces(args.root)
        if args.cmd == "check":
            files = g.read_file_list(args.files_from) if args.files_from else tracked_files(args.root)
            sv, notes = structure_violations(s)
            v = (_tag(MAP, sv + exempt_violations(s, args.root))
                 + _tag("surface_guard.ownership", ownership_violations(s, files)))
            return g.report(args.root, v, notes,
                            "surface map is coherent; %d file(s) each have exactly one owner" % len(set(files)))
        if args.cmd == "diff" and args.range is not None:
            return run_range(args, s)
        if args.cmd == "diff":
            files = g.read_file_list(args.files_from) if args.files_from else changed_files(args.root, args.base)
            v = diff_violations(s, args.agent, files)
            return g.report(args.root, _tag("surface_guard.diff", v), [],
                            "%d changed file(s) all inside the surface of '%s'" % (len(set(files)), args.agent))
        if args.cmd == "charters":
            v, notes, n = check_charters(s, args.root, write=args.write)
            return g.report(args.root, _tag("surface_guard.charters", v), notes,
                            "%d builder charter(s) %s" % (n, "written or already current" if args.write
                                                          else "match %s" % SF))
        if args.cmd == "whois":
            bad = 0
            for p in args.paths:
                path = p
                owners = s.owners(path)
                if len(owners) == 1:
                    print("%s: %s" % (path, owners[0]))
                elif not owners:
                    bad += 1
                    print("%s: UNOWNED" % path)
                else:
                    bad += 1
                    print("%s: CLAIMED BY %s" % (path, ", ".join(owners)))
            return 1 if bad else 0
    except g.UsageError as exc:
        print("ERROR: %s" % exc, file=sys.stderr)
        return 2
    return 2


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""review_check — required reviews from risk-paths.toml, verdicts from reviews/.

Usage:
  review_check.py lint     [--root DIR]
  review_check.py pr PR    --base REF [--root DIR] [--files-from FILE] [--summary-json FILE]
  review_check.py classify PATH... [--root DIR]
  review_check.py questions --default-branch NAME --summary-json FILE [--root DIR]

Reads governance/risk-paths.toml (a path's risk class and the reviews a change
needs), governance/SURFACES.md (the reviewer-class roster) and the verdict
files reviews/<PR>/<reviewer-id>.md (spec S-002). `owner` is the reserved
reviewer id of the human owner. Requires Python 3.11+ (tomllib).

`pr` also raises flags (spec S-003), each of which adds `owner` to the
required reviews: a changed test file ([tests] globs) that was deleted, gained
a line with a skip marker or a broad catch, or has fewer assertions; and any
changed dependency manifest ([dependencies] manifests). An added dependency
that isn't pinned (requirements*.txt without `==`; a package.json
dependencies/devDependencies range) fails outright. Contents are compared
between the merge base of BASE and HEAD, and HEAD. These are text heuristics.

`pr --summary-json FILE` also writes the owner's state as JSON on every exit
path (spec S-004 AC1): other_findings, owner_action, risk and reasons.
`questions` (spec S-004 AC3) writes the open question files as JSON: on the
default branch (HEAD is origin/NAME) every questions/*.md not starting with
'_'; elsewhere those that differ from the merge base with origin/NAME. It is
not a check; only CI's record step runs it (exit 0, or 2 with an error summary).
Exit 0 = pass, 1 = rule violated, 2 = usage or parse error.
"""

import sys

if sys.version_info < (3, 11):
    print("ERROR: Python 3.11+ is required (tomllib)", file=sys.stderr)
    sys.exit(2)

import argparse  # noqa: E402
import difflib  # noqa: E402
import json  # noqa: E402
import os  # noqa: E402
import re  # noqa: E402
import unicodedata  # noqa: E402

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import govlib as g  # noqa: E402

REVIEWS_REL = "reviews"
PR_RE = re.compile(r"^[A-Za-z0-9._-]+$")
VERDICT_RE = re.compile(r"^Verdict: (PASS|FAIL)[ \t]*$")
SETTERS_CAP = 10


def _lead_stripped(line):
    """The line without leading whitespace and Unicode format (Cf) characters."""
    i = 0
    while i < len(line) and (line[i].isspace() or unicodedata.category(line[i]) == "Cf"):
        i += 1
    return line[i:]

        why = "required by %s" % ", ".join(required[rid])
        if (pr, rid) not in verdicts:
            v.append((_required_check(rid), "missing verdict: %s (%s)" % (rel, why)))
        elif verdicts[(pr, rid)] == "FAIL":
            v.append((_required_check(rid), "%s: verdict is FAIL (%s)" % (rel, why)))
        else:
            continue   # PASS; a malformed verdict is reported above.
        if rid == g.OWNER:
            state["owner_own"].add(len(v) - 1)   # the owner's own missing or FAIL verdict
    for (vpr, stem) in sorted(verdicts):
        if vpr == pr and stem not in required:
            notes.append("NOTE: %s/%s/%s.md: verdict from '%s', which this change does not require"
                         % (REVIEWS_REL, pr, stem, stem))
    return g.report(args.root, v, notes, "PR %s (%s): %d required verdict(s), all PASS" % (pr, cls, len(required)),
                    enforcement=lt.enforcement)


# --------------------------------------------------------------------------
# Spec S-004: the owner summary (AC1) and the questions subcommand (AC3)

REASON_CODES = ("R0", "R1", "R2", "R3", "test-weakening", "dependency", "domain")
_FLAG_CODES = {FLAG_REASONS["test"]: "test-weakening", FLAG_REASONS["dependency"]: "dependency"}


def reason_codes(reasons):
    """Map the owner's requirement reasons to the fixed codes (AC1), in the fixed order."""
    codes = set()
    for r in reasons:
        if r in g.RISK_CLASSES:
            codes.add(r)
        elif r in _FLAG_CODES:
            codes.add(_FLAG_CODES[r])
        elif r.startswith("domain "):
            codes.add("domain")
    return [c for c in REASON_CODES if c in codes]


def owner_summary(rc, state):
    """The AC1 summary of a `pr` run that exited with `rc`, from the state cmd_pr recorded."""
    findings = state.get("findings", [])
    enf = state.get("enforcement")
    own = state.get("owner_own", set())
    other = 0
    for i, (name, _) in enumerate(findings):
        if i in own:
            continue
        # Enforced findings, and every verdicts finding even when warn-only.
        if name == "review_check.verdicts" or enf is None or not enf.ledger_for(name):
            other += 1
    required = state.get("required") or {}
    verdict = state.get("owner_verdict", "missing")
    if rc == 2 or "required" not in state or any(n == "review_check.config" for n, _ in findings):
        action = "error"
    elif g.OWNER not in required:
        action = "not_required"
    elif verdict is None:
        action = "error"
    elif verdict == "FAIL":
        action = "changes_requested"
    elif verdict == "PASS":
        action = "approved"
    elif other > 0:
        action = "after_agents"
    else:
        action = "needed"
    return {
        "other_findings": other,
        "owner_action": action,
        "risk": state.get("risk"),
        "reasons": reason_codes(required.get(g.OWNER, [])),
    }


def write_json(path, data):
    """Write data as one line of JSON (then a newline) to path."""
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(json.dumps(data, sort_keys=True, separators=(",", ":")) + "\n")
    os.replace(tmp, path)


QUESTIONS_REL = "questions"


def question_files_at_head(root):
    """questions/*.md at HEAD whose names don't start with '_' (names read NUL-separated)."""
    out = []
    for path in g.split_z(g.git(root, ["ls-tree", "-z", "--name-only", "HEAD", "--", QUESTIONS_REL + "/"])):
        name = path[len(QUESTIONS_REL) + 1:] if path.startswith(QUESTIONS_REL + "/") else ""
        if name and "/" not in name and name.endswith(".md") and not name.startswith("_"):
            out.append(path)
    return sorted(out)


def open_questions(root, default_branch):
    """Return the open question files (AC3). Raises UsageError when they can't be decided."""
    if not default_branch or default_branch.startswith("-") or not g.git_ok(
            root, ["check-ref-format", "--branch", default_branch]):
        raise g.UsageError("default branch %r is not a branch name" % default_branch)
    ref = "refs/remotes/origin/%s" % default_branch
    if not g.git_ok(root, ["rev-parse", "--verify", "-q", "%s^{commit}" % ref]):
        raise g.UsageError("origin/%s is not a commit in %s" % (default_branch, root))
    head = g.git(root, ["rev-parse", "--verify", "HEAD^{commit}"]).decode().strip()
    tip = g.git(root, ["rev-parse", "--verify", "%s^{commit}" % ref]).decode().strip()
    files = question_files_at_head(root)
    if head == tip:
        return files
    if not g.git_ok(root, ["merge-base", ref, "HEAD"]):
        raise g.UsageError("no merge base between origin/%s and HEAD" % default_branch)
    base = g.git(root, ["merge-base", ref, "HEAD"]).decode().strip()
    changed = set(g.split_z(g.git(root, ["diff", "--name-only", "--no-renames", "-z", base, "HEAD",
                                         "--", QUESTIONS_REL + "/"])))
    return [p for p in files if p in changed]


def cmd_questions(args):
    try:
        files = open_questions(args.root, args.default_branch)
    except g.UsageError as exc:
        print("ERROR: %s" % exc, file=sys.stderr)
        write_json(args.summary_json, {"state": "error", "open": None, "files": []})
        return 2
    write_json(args.summary_json, {"state": "ok", "open": len(files), "files": files})
    print("Open questions: %d" % len(files))
    for p in files:
        print("  %s" % p)
    return 0


def cmd_classify(args):
    s = g.load_surfaces(args.root) if os.path.isfile(os.path.join(args.root, g.SURFACES_REL)) else None
    rp, problems = g.load_risk_paths(args.root, s.reviewer_ids() if s else [])
    if rp is None:
        raise g.UsageError("; ".join(problems))
    for p in problems:
        print("NOTE: %s" % p)
    for path in args.paths:
        print("%s: %s" % (path, rp.path_class(g.normalize_path(path))))
    return 0


def main(argv=None):
    parser = argparse.ArgumentParser(prog="review_check.py", description=__doc__.split("\n")[0])
    sub = parser.add_subparsers(dest="cmd")
    p_lint = sub.add_parser("lint")
    p_lint.add_argument("--root", default=".")
    p_pr = sub.add_parser("pr")
    p_pr.add_argument("pr")
    p_pr.add_argument("--base")
    p_pr.add_argument("--root", default=".")
    p_pr.add_argument("--files-from")
    p_pr.add_argument("--summary-json")
    p_q = sub.add_parser("questions")
    p_q.add_argument("--default-branch", required=True)
    p_q.add_argument("--summary-json", required=True)
    p_q.add_argument("--root", default=".")
    p_cls = sub.add_parser("classify")
    p_cls.add_argument("paths", nargs="+")
    p_cls.add_argument("--root", default=".")
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        _summary_after_usage_error(argv, exc.code)
        return 2 if exc.code else 0
    if not args.cmd:
        parser.print_usage(sys.stderr)
        return 2
    if args.cmd == "pr":
        return run_pr(args)
    try:
        if args.cmd == "lint":
            return cmd_lint(args)
        if args.cmd == "questions":
            return cmd_questions(args)
        if args.cmd == "classify":
            return cmd_classify(args)
    except g.UsageError as exc:
        print("ERROR: %s" % exc, file=sys.stderr)
        return 2
    return 2


def _write_summary(path, rc, state):
    """Write the AC1 summary; on failure, say so and return 2."""
    try:
        write_json(path, owner_summary(rc, state))
    except OSError as exc:
        print("ERROR: can't write the summary %s: %s" % (path, exc), file=sys.stderr)
        return 2
    return rc


def run_pr(args):
    """`pr`, writing --summary-json on every exit path (AC1)."""
    state = {}
    rc = 2
    try:
        if not args.base and not args.files_from:
            print("ERROR: pr needs --base REF (or --files-from FILE)", file=sys.stderr)
        else:
            try:
                rc = cmd_pr(args, state)
            except g.UsageError as exc:
                print("ERROR: %s" % exc, file=sys.stderr)
                rc = 2
    finally:
        # An unexpected exception still leaves an `error` summary behind (rc stays 2).
        if args.summary_json:
            rc = _write_summary(args.summary_json, rc, state)
    return rc


def _summary_after_usage_error(argv, code):
    """A `pr` command line argparse rejected still gets an `error` summary, if it names a file."""
    argv = list(sys.argv[1:] if argv is None else argv)
    if not code or not argv or argv[0] != "pr":
        return
    path = None
    for i, a in enumerate(argv):
        if a == "--summary-json" and i + 1 < len(argv):
            path = argv[i + 1]
        elif a.startswith("--summary-json="):
            path = a.split("=", 1)[1]
    if path:
        _write_summary(path, 2, {})


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""owner_signal — publish whether the owner is needed as two commit statuses (spec S-004).

Usage:
  owner_signal.py record --dir DIR [--test ID=OUTCOME ...] [--output FILE]
  owner_signal.py post   [--dry-run] [--root DIR]

`record` runs as the checks job's last step. It reads DIR/steps.json and
DIR/review.json (written by check_all.sh under GOV_SUMMARY_DIR) and
DIR/questions.json (written by `review_check.py questions`), and writes them,
with each test step's outcome, as the job outputs `tests`, `steps`, `review`
and `questions` (to FILE, default $GITHUB_OUTPUT). A missing or unparseable
file gives an empty output.

`post` runs in the final `owner-signal` job, from the default branch's
checkout. Every input comes from the environment:
  EVENT_NAME   pull_request or push
  PR_HEAD_SHA  pull_request.head.sha (the status target on pull_request)
  PR_BASE_SHA  pull_request.base.sha (the tripwire diff's base)
  GITHUB_SHA   the status target on push
  TESTS, STEPS, REVIEW, QUESTIONS   the checks job's outputs
  GITHUB_REPOSITORY, GITHUB_SERVER_URL, GITHUB_RUN_ID   the repository and run URL
  GH_TOKEN     used by `gh api`
It posts `owner-verdict` (pull_request only) and `owner-questions` with
`gh api`. Descriptions hold only fixed words, counts and reason codes, cut to
140 characters. The owner-verdict tripwire (AC6) diffs PR_BASE_SHA...PR_HEAD_SHA
in this checkout against the default branch's signal_code list
(governance/risk-paths.toml, else the defaults); if the diff can't run or the
list is invalid, it posts an error, never a pass.

Standard library only; Python 3.11+ (tomllib). Exit 0 = every status posted
(or printed with --dry-run), 1 = a post failed, 2 = usage error.
"""

import sys

if sys.version_info < (3, 11):
    print("ERROR: Python 3.11+ is required (tomllib)", file=sys.stderr)
    sys.exit(2)

import argparse  # noqa: E402
import json  # noqa: E402
import os  # noqa: E402
import re  # noqa: E402
import subprocess  # noqa: E402

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import govlib as g  # noqa: E402

VERDICT = "owner-verdict"
QUESTIONS = "owner-questions"
MAX_DESCRIPTION = 140
OUTCOMES = ("success", "failure", "cancelled", "skipped")
REVIEW_STEP_PREFIX = "review_check pr "
OWNER_ACTIONS = ("error", "not_required", "changes_requested", "approved", "after_agents", "needed")
REASON_CODES = ("R0", "R1", "R2", "R3", "test-weakening", "dependency", "domain")
SHA_RE = re.compile(r"^[0-9a-f]{40}$")
REPO_RE = re.compile(r"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$")
TEST_ID_RE = re.compile(r"^[A-Za-z0-9_-]+$")

NO_SUMMARY = "CI produced no summary"
TRIPWIRE_FAILED = "Tripwire couldn't run"
TRIPWIRE_TRIPPED = "CI code changed · check the PR"


class Invalid(Exception):
    """An input that is empty, unparseable or not in the expected shape."""


def describe(text):
    """A status description: at most 140 characters (F10)."""
    return text[:MAX_DESCRIPTION]


# --------------------------------------------------------------------------
# Parsing the checks job's outputs. Anything unexpected is Invalid.


def _load(text):
    if not isinstance(text, str) or not text.strip():
        raise Invalid("empty")
    try:
        return json.loads(text)
    except ValueError:
        raise Invalid("not JSON")


def _count(value):
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise Invalid("not a count")
    return value


def parse_review(text):
    data = _load(text)
    if not isinstance(data, dict):
        raise Invalid("review summary is not an object")
    action = data.get("owner_action")
    if action not in OWNER_ACTIONS:
        raise Invalid("owner_action")
    other = _count(data.get("other_findings"))
    reasons = data.get("reasons")
    if not isinstance(reasons, list) or any(r not in REASON_CODES for r in reasons):
        raise Invalid("reasons")
    risk = data.get("risk")
    if risk is not None and risk not in g.RISK_CLASSES:
        raise Invalid("risk")
    return {"owner_action": action, "other_findings": other, "reasons": reasons, "risk": risk}


def parse_steps(text):
    data = _load(text)
    if not isinstance(data, list) or not data:
        raise Invalid("steps summary is not a non-empty list")
    out = []
    for item in data:
        if not isinstance(item, dict) or not isinstance(item.get("name"), str) or not item["name"]:
            raise Invalid("step")
        if isinstance(item.get("exit"), bool) or not isinstance(item.get("exit"), int):
            raise Invalid("step exit")
        out.append((item["name"], item["exit"]))
    return out


def parse_tests(text):
    data = _load(text)
    if not isinstance(data, dict) or not data:
        raise Invalid("tests summary is not a non-empty object")
    for value in data.values():
        if value not in OUTCOMES:
            raise Invalid("test outcome")
    return dict(data)


def parse_questions(text):
    data = _load(text)
    if not isinstance(data, dict) or data.get("state") not in ("ok", "error"):
        raise Invalid("questions summary")
    if data["state"] == "ok":
        _count(data.get("open"))
    return data


# --------------------------------------------------------------------------
# The mapping (AC2, AC4): a pure function from inputs to statuses.


def verdict_status(review_text, steps_text, tests_text):
    """(state, description) for owner-verdict, from the checks job's outputs."""
    try:
        review = parse_review(review_text)
        steps = parse_steps(steps_text)
        tests = parse_tests(tests_text)
    except Invalid:
        return "error", NO_SUMMARY
    review_steps = [rc for name, rc in steps if name.startswith(REVIEW_STEP_PREFIX)]
    if len(review_steps) != 1:
        # A review summary without exactly one `review_check pr` step doesn't add up.
        return "error", NO_SUMMARY
    action = review["owner_action"]
    if action == "error":
        return "error", "Owner state unknown · review check error"
    if action == "not_required":
        return "success", "Owner not required"
    if action == "changes_requested":
        return "failure", "Owner requested changes"
    if action == "approved":
        return "success", "Owner approved"
    if action == "after_agents":
        return "pending", "Owner: after agents · %d other finding(s)" % review["other_findings"]
    # needed: only when every other check_all step passed and every test step succeeded.
    others_pass = all(rc == 0 for name, rc in steps if not name.startswith(REVIEW_STEP_PREFIX))
    tests_pass = all(outcome == "success" for outcome in tests.values())
    if not (others_pass and tests_pass and review["other_findings"] == 0):
        return "pending", "Owner: after agents · other checks failing"
    reasons = ", ".join(review["reasons"])
    return "pending", "Owner verdict needed" + (" · " + reasons if reasons else "")


def questions_status(questions_text):
    """(state, description) for owner-questions."""
    try:
        q = parse_questions(questions_text)
    except Invalid:
        return "error", NO_SUMMARY
    if q["state"] == "error":
        return "error", "Questions unknown"
    if q["open"]:
        return "pending", "%d open question(s)" % q["open"]
    return "success", "No open questions"


def target_sha(env):
    """The commit the statuses go on: the PR head on pull_request, github.sha otherwise."""
    if env.get("EVENT_NAME") == "pull_request":
        return env.get("PR_HEAD_SHA", "")
    return env.get("GITHUB_SHA", "")


def statuses(env, tripwire=None):
    """[(context, state, description)] to post for this run.

    `tripwire` is None (not run), or (ok, tripped): ok False means it couldn't run."""
    out = []
    if env.get("EVENT_NAME") == "pull_request":
        if tripwire is None or not tripwire[0]:
            state, desc = "error", TRIPWIRE_FAILED
        elif tripwire[1]:
            state, desc = "error", TRIPWIRE_TRIPPED
        else:
            state, desc = verdict_status(env.get("REVIEW", ""), env.get("STEPS", ""), env.get("TESTS", ""))
        out.append((VERDICT, state, describe(desc)))
    state, desc = questions_status(env.get("QUESTIONS", ""))
    out.append((QUESTIONS, state, describe(desc)))
    return out


# --------------------------------------------------------------------------
# The tripwire (AC6)


def signal_code(root):
    """The default branch's signal_code list. Raises Invalid when it can't be trusted."""
    path = os.path.join(root, g.RISK_PATHS_REL)
    if not os.path.isfile(path):
        return list(g.SIGNAL_CODE_DEFAULTS)
    try:
        data, err = g.load_toml(g.read_text(path, newline=""), g.RISK_PATHS_REL)
    except g.UsageError:
        raise Invalid("risk-paths.toml can't be read")
    if err:
        raise Invalid("risk-paths.toml is not valid TOML")
    if "signal_code" not in data:
        return list(g.SIGNAL_CODE_DEFAULTS)
    value, problem = g.check_signal_code(data["signal_code"])
    if problem:
        raise Invalid(problem)
    return value


def run_tripwire(root, base, head):
    """(ok, tripped). ok is False when the diff can't run or signal_code is invalid (never fails open)."""
    try:
        globs = signal_code(root)
    except Invalid:
        return False, False
    if not SHA_RE.match(base or "") or not SHA_RE.match(head or ""):
        return False, False
    proc = subprocess.run(["git", "diff", "--name-only", "--no-renames", "-z", "%s...%s" % (base, head)],
                          cwd=root, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if proc.returncode != 0:
        return False, False
    paths = g.split_z(proc.stdout)
    return True, any(g.glob_match(gl, p) for p in paths for gl in globs)


# --------------------------------------------------------------------------
# Commands


def run_url(env):
    server, repo, run = env.get("GITHUB_SERVER_URL", ""), env.get("GITHUB_REPOSITORY", ""), env.get("GITHUB_RUN_ID", "")
    if server and REPO_RE.match(repo) and run.isdigit():
        return "%s/%s/actions/runs/%s" % (server, repo, run)
    return ""


def gh_post(repo, sha, context, state, description, url):
    """POST one commit status with `gh api`; return True on success."""
    cmd = ["gh", "api", "--method", "POST", "repos/%s/statuses/%s" % (repo, sha),
           "-f", "state=%s" % state, "-f", "context=%s" % context, "-f", "description=%s" % description]
    if url:
        cmd += ["-f", "target_url=%s" % url]
    try:
        proc = subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
    except OSError as exc:
        print("ERROR: can't run gh: %s" % exc, file=sys.stderr)
        return False
    if proc.returncode != 0:
        print("ERROR: posting %s failed: %s" % (context, proc.stderr.decode("utf-8", "replace").strip()),
              file=sys.stderr)
        return False
    return True


def cmd_post(args, env=None, poster=gh_post):
    env = dict(os.environ if env is None else env)
    sha = target_sha(env)
    if not SHA_RE.match(sha):
        print("ERROR: target commit %r is not a 40-character SHA" % sha, file=sys.stderr)
        return 2
    repo = env.get("GITHUB_REPOSITORY", "")
    if not args.dry_run and not REPO_RE.match(repo):
        print("ERROR: GITHUB_REPOSITORY %r is not owner/name" % repo, file=sys.stderr)
        return 2
    tripwire = None
    if env.get("EVENT_NAME") == "pull_request":
        tripwire = run_tripwire(args.root, env.get("PR_BASE_SHA", ""), sha)
    url = run_url(env)
    ok = True
    for context, state, desc in statuses(env, tripwire):
        print("%s %s: %s" % (context, state, desc))
        if not args.dry_run:
            ok = poster(repo, sha, context, state, desc, url) and ok
    return 0 if ok else 1


def _read_summary(path):
    """One line of JSON from path, or '' when it is missing or unparseable."""
    try:
        with open(path, encoding="utf-8") as fh:
            return json.dumps(json.load(fh), sort_keys=True, separators=(",", ":"))
    except (OSError, ValueError):
        return ""


def record_outputs(summary_dir, tests):
    """{output name: one-line value} for the checks job's outputs."""
    out = {}
    valid = all(TEST_ID_RE.match(k) and v in OUTCOMES for k, v in tests)
    out["tests"] = json.dumps(dict(tests), sort_keys=True, separators=(",", ":")) if tests and valid else ""
    for name, rel in (("steps", "steps.json"), ("review", "review.json"), ("questions", "questions.json")):
        out[name] = _read_summary(os.path.join(summary_dir, rel))
    return out


def cmd_record(args, env=None):
    env = os.environ if env is None else env
    tests = []
    for item in args.test or []:
        key, sep, value = item.partition("=")
        tests.append((key, value) if sep else (key, ""))
    target = args.output or env.get("GITHUB_OUTPUT", "")
    if not target:
        print("ERROR: record needs --output FILE or GITHUB_OUTPUT", file=sys.stderr)
        return 2
    outputs = record_outputs(args.dir, tests)
    with open(target, "a", encoding="utf-8") as fh:
        for name in ("tests", "steps", "review", "questions"):
            value = outputs[name]
            assert "\n" not in value and "\r" not in value
            fh.write("%s=%s\n" % (name, value))
            print("%s: %s" % (name, "recorded" if value else "empty"))
    return 0


def main(argv=None):
    parser = argparse.ArgumentParser(prog="owner_signal.py", description=__doc__.split("\n")[0])
    sub = parser.add_subparsers(dest="cmd")
    p_rec = sub.add_parser("record")
    p_rec.add_argument("--dir", required=True)
    p_rec.add_argument("--test", action="append")
    p_rec.add_argument("--output")
    p_post = sub.add_parser("post")
    p_post.add_argument("--dry-run", action="store_true")
    p_post.add_argument("--root", default=".")
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return 2 if exc.code else 0
    if args.cmd == "record":
        return cmd_record(args)
    if args.cmd == "post":
        return cmd_post(args)
    parser.print_usage(sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main())

def parse_verdict(text):
    """Return 'PASS', 'FAIL' or None (malformed).

    One leading UTF-8 BOM is dropped. The deciding line is the first line that,
    after removing leading whitespace and format (Cf) characters, starts with
    `Verdict:`. That line, as written, must read exactly `Verdict: PASS` or
    `Verdict: FAIL` (one space after the colon), optionally followed by spaces
    or tabs. Lines split on LF only, and one trailing CR is dropped, so no other
    character (form feed, \\x1c, U+2028 ...) ends a line. Any line on which
    `Verdict:` appears anywhere but at the start makes the file malformed
    (spec S-003 §6)."""
    if text.startswith("\ufeff"):
        text = text[1:]
